package id.melawai.pegawai;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.webkit.*;import androidx.webkit.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 WebView web;boolean pendingTracking=false;ValueCallback<Uri[]> files;PermissionRequest camera;
 protected void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);setContentView(web);web.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in;});
 WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);
 if(WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))WebViewCompat.addWebMessageListener(web,"MelawaiNative",Collections.singleton(AppConfig.ORIGIN),(view,msg,origin,main,reply)->{if(!main||!AppConfig.trusted(Uri.parse(view.getUrl()==null?"":view.getUrl())))return;try{JSONObject j=new JSONObject(msg.getData());String type=j.optString("type");if(type.equals("init")){String id=getPreferences(0).getString("device","");if(id.isEmpty()){id=UUID.randomUUID().toString();getPreferences(0).edit().putString("device",id).apply();}reply.postMessage(new JSONObject().put("type","init").put("device_id",id).put("has_token",false).toString());}else if(type.equals("token")){stopService(new Intent(this,TrackingService.class));TokenStore.save(this,j.getString("token"));}else if(type.equals("tracking")){if(j.optBoolean("active"))askTracking();else stopService(new Intent(this,TrackingService.class));}}catch(Exception e){Toast.makeText(this,"Koneksi aplikasi belum siap. Muat ulang halaman.",Toast.LENGTH_SHORT).show();}});else new AlertDialog.Builder(this).setMessage("Perbarui Android System WebView agar GPS aplikasi dapat digunakan.").setPositiveButton("OK",null).show();
 web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest req){Uri u=req.getUrl();if(AppConfig.trusted(u))return false;if(Arrays.asList("https","http","tel","mailto").contains(u.getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}public void onPageStarted(WebView v,String url,android.graphics.Bitmap icon){if(url.contains("/logout")){stopService(new Intent(MainActivity.this,TrackingService.class));TokenStore.clear(MainActivity.this);}}public void onReceivedError(WebView v,WebResourceRequest req,WebResourceError err){if(req.isForMainFrame())Toast.makeText(MainActivity.this,"Koneksi gagal. Periksa internet, lalu buka ulang aplikasi.",Toast.LENGTH_LONG).show();}});
 web.setWebChromeClient(new WebChromeClient(){public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback cb){boolean ok=origin.equals(AppConfig.ORIGIN)&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;cb.invoke(origin,ok,false);if(!ok)requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},11);}public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=cb;try{startActivityForResult(p.createIntent(),12);}catch(Exception e){files.onReceiveValue(null);files=null;}return true;}public void onPermissionRequest(PermissionRequest req){runOnUiThread(()->{if(!req.getOrigin().toString().equals(AppConfig.ORIGIN)) {req.deny();return;}camera=req;if(checkSelfPermission(android.Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)grantCamera();else requestPermissions(new String[]{android.Manifest.permission.CAMERA},13);});}});
 web.setDownloadListener((url,ua,disposition,mime,length)->{if(!AppConfig.trusted(Uri.parse(url)))return;try{DownloadManager.Request req=new DownloadManager.Request(Uri.parse(url));String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null)req.addRequestHeader("Cookie",cookie);req.addRequestHeader("User-Agent",ua);req.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);req.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,URLUtil.guessFileName(url,disposition,mime));((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(req);Toast.makeText(this,"Unduhan dimulai.",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Unduhan gagal.",Toast.LENGTH_LONG).show();}});
 web.loadUrl(AppConfig.BASE+"/");}
 void grantCamera(){if(camera==null)return;ArrayList<String> granted=new ArrayList<>();for(String resource:camera.getResources())if(resource.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE))granted.add(resource);if(granted.isEmpty())camera.deny();else camera.grant(granted.toArray(new String[0]));camera=null;}
 void askTracking(){if(TokenStore.read(this).isEmpty())return;pendingTracking=true;if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(this).setMessage("Lokasi digunakan selama Anda bertugas, termasuk saat layar terkunci. Notifikasi pelacakan akan terlihat. Izinkan lokasi akurat untuk melanjutkan.").setPositiveButton("Izinkan",(d,w)->requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},11)).setNegativeButton("Batal",(d,w)->pendingTracking=false).show();return;}if(Build.VERSION.SDK_INT>=33 && checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},14);return;}startTracking();}
 void startTracking(){if(isFinishing()||TokenStore.read(this).isEmpty())return;pendingTracking=false;try{startForegroundService(new Intent(this,TrackingService.class));}catch(Exception e){Toast.makeText(this,"GPS belum aktif. Buka kembali halaman Jam Kerja.",Toast.LENGTH_LONG).show();}}
 public void onRequestPermissionsResult(int code,String[] p,int[] g){super.onRequestPermissionsResult(code,p,g);if(code==13){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)grantCamera();else if(camera!=null){camera.deny();camera=null;}}else if(code==14){startTracking();}else if(code==11){if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED){if(pendingTracking)askTracking();else web.reload();}else{pendingTracking=false;Toast.makeText(this,"Lokasi akurat diperlukan. Aktifkan izin di Pengaturan.",Toast.LENGTH_LONG).show();}}}
 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==12&&files!=null){files.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));files=null;}}
 public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 protected void onPause(){CookieManager.getInstance().flush();super.onPause();}
}
